mapper.select:
SELECT c.class_id AS clssId, c.name AS name, c.target_grade AS targetGrade, c.max_students AS maxStudents, c.status AS status, c.created_at AS createdAt, u.name AS mainTeacherName FROM classes c LEFT JOIN class_teachers ct ON c.class_id = ct.class_id AND ct.role_type = 'MAIN' LEFT JOIN users u ON ct.teacher_id = u.user_id WHERE c.academy_id = #{academyId}
AND c.status = #{status}
ORDER BY c.class_id DESC
